<script setup lang="ts">
import { onMounted, ref } from 'vue'
import AsyncState from '@/components/AsyncState.vue'
import ModalDialog from '@/components/ModalDialog.vue'
import { api, apiErrorMessage } from '@/api/client'
import type { AdapterManifest, TaskRef } from '@/api/types'
import { useAppStore } from '@/stores/app'
import { useTaskStore } from '@/stores/tasks'
const app = useAppStore(); const tasks = useTaskStore(); const manifests = ref<AdapterManifest[]>([]); const loading = ref(true); const error = ref(''); const selected = ref<AdapterManifest | null>(null)
async function load() { loading.value = true; error.value = ''; try { manifests.value = await api.get<AdapterManifest[]>('/adapters') } catch (value) { error.value = apiErrorMessage(value) } finally { loading.value = false } }
async function test(item: AdapterManifest) { try { const task = await api.post<TaskRef>(`/adapters/${item.id}/test`); tasks.track(task, `测试 ${item.name || item.id} 适配器`); app.taskDrawerOpen = true } catch (value) { app.toast(apiErrorMessage(value), 'error') } }
onMounted(load)
</script>
<template><section class="card"><div class="card-header"><div><h2>适配器</h2><p class="subtle-text">由后端 manifest 驱动的网站与账号配置</p></div><button class="button secondary small" @click="load">刷新</button></div><AsyncState :loading="loading" :error="error" :empty="!manifests.length" empty-title="未发现适配器" empty-text="安装或启用适配器后会显示在这里。" @retry="load"><div class="adapter-list"><article v-for="item in manifests" :key="item.id" class="adapter-row"><span class="adapter-icon">A</span><div><div class="row"><strong>{{ item.name || item.id }}</strong><span class="tag">v{{ item.version }}</span></div><p>{{ item.description || 'SiteHub 适配器' }}</p><div class="tag-list"><span v-for="capability in item.capabilities" :key="capability" class="tag">{{ capability }}</span></div></div><div class="adapter-actions"><button class="text-button" @click="selected = item">查看</button><button class="button secondary small" @click="test(item)">自检</button></div></article></div></AsyncState></section><ModalDialog v-if="selected" title="适配器详情" wide @close="selected = null"><div class="manifest-detail"><div class="row-between"><div><h3>{{ selected.name || selected.id }}</h3><p>{{ selected.id }} · v{{ selected.version }}</p></div><div class="tag-list"><span v-for="cap in selected.capabilities" :key="cap" class="tag">{{ cap }}</span></div></div><dl><div><dt>网站配置字段</dt><dd>{{ Object.keys(selected.site_config_schema?.properties || {}).length }}</dd></div><div><dt>账号配置字段</dt><dd>{{ Object.keys(selected.account_config_schema?.properties || {}).length }}</dd></div><div><dt>密钥字段</dt><dd>{{ selected.secret_fields.length ? selected.secret_fields.join('、') : '无' }}</dd></div></dl><p class="privacy-note">密钥字段只显示配置状态，SiteHub API 永不向页面返回密钥值。</p></div></ModalDialog></template>
<style scoped>.adapter-list { display: flex; flex-direction: column; }.adapter-row { display: grid; grid-template-columns: 40px 1fr auto; gap: 13px; padding: 17px 18px; border-bottom: 1px solid var(--line); }.adapter-row:last-child { border: 0; }.adapter-icon { display: grid; width: 38px; height: 38px; place-items: center; border-radius: 10px; color: var(--accent); background: var(--accent-soft); font-weight: 700; }.adapter-row p { margin: 4px 0 8px; font-size: 12px; }.adapter-actions { display: flex; align-items: center; gap: 9px; }.manifest-detail h3 { margin: 0; }.manifest-detail p { margin: 4px 0 0; }.manifest-detail dl { margin: 20px 0; border: 1px solid var(--line); border-radius: 9px; }.manifest-detail dl div { display: grid; grid-template-columns: 170px 1fr; padding: 11px 13px; border-bottom: 1px solid var(--line); }.manifest-detail dl div:last-child { border: 0; }.manifest-detail dt { color: var(--muted); }.manifest-detail dd { margin: 0; }.privacy-note { padding: 12px; border-radius: 8px; color: var(--positive) !important; background: var(--positive-soft); font-size: 12px; } @media (max-width: 540px) { .adapter-row { grid-template-columns: 40px 1fr; }.adapter-actions { grid-column: 2; } }</style>
